SELECT
  if(count() > 0, 'Connected', 'Not Connected') AS qres,
  99 AS v
FROM ${table}
WHERE datetime > NOW() - INTERVAL 30 MINUTE
  AND ${generalescaping}
  AND $__adHocFilter() 
SETTINGS 
  hdx_query_max_execution_time=60, 
  hdx_query_admin_comment='db=${__dashboard}; dp=Status; du=${__user.login}'

SELECT count(DISTINCT username) AS querycontroller, 99 as v
FROM ${table}
WHERE datetime > NOW() - INTERVAL 30 MINUTE
  AND ${generalescaping}
  AND $__adHocFilter()
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=ActiveUserCount; du=${__user.login}'

SELECT username, origin, maxOrNull(datetime) as Last_Access FROM ${table} 
WHERE $__timeFilter(datetime) 
AND ${generalescaping}
AND $__adHocFilter() 
AND username != '-'
AND origin != '-'
group by username, origin 
order by Last_Access desc
limit ${querieslimit} 
SETTINGS hdx_query_max_execution_time=60, hdx_query_admin_comment='db=${__dashboard}; dp=Last ${querieslimit} origin details; du=${__user.login}'

